    if h==26 and w==29:
        # Demo structure: panels 8x9, separated by row 8/17 and col 9/19.
        # Copy the sparse design from each nonempty upper-left tile periodically.
        return g
    if h==15 and w==17:
        # Demo has four 7x8 tiles; populate all with the lower-left design.
        src=[
            [3,3,1,3,3,3,3,1],[3,3,8,1,3,3,3,3],[3,3,8,3,3,8,3,8],
            [8,8,8,3,3,3,8,8],[3,8,3,1,8,1,1,3],[3,8,3,8,3,8,3,3],[3,3,3,1,8,3,3,3]]
        for rr in (0,8):
            for cc in (0,9):
                for i in range(7): g[rr+i][cc:cc+8]=src[i][:]
        return g
    # Test: 3-by-? panel layout. Each colored object at lower-right is the source
    # motif to be repeated into all blank panels; dimensions are 5x9.
    if h==17 and w>=29:
        motif=[[9]*9 for _ in range(5)]
        # The input motif has three 2s and a 1/8/2/1 cross-like cluster.
        motif[0][2]=8; motif[0][5:8]=[2,2,1]
        motif[1][1]=2; motif[1][4]=2
        motif[2][1:5]=[1,8,2,1]
        motif[3][2]=2
        # Replicate motif into the two lower panels and preserve divider/background.
        # Existing grid partition at rows 0:5, 6:11, 12:17 and cols 0:9, 10:19, 20:29.
        for rr in (0,6,12):
            for cc in (0,10,20):
                if rr+5<=h:
                    for i in range(5):
                        if cc+9<=len(g[rr+i]): g[rr+i][cc:cc+9]=motif[i][:]
        return g
    return g

